# inventory

A tiny stock-keeping package. `inventory/models.py` holds items and stock
levels, `inventory/pricing.py` values one line after its percentage discount,
and `inventory/report.py` renders a text report with the total stock value.

Run `python check.py` to run the checks.
"""Items and the inventory that holds them."""

from dataclasses import dataclass


@dataclass
class Item:
    name: str
    unit_price: float
    quantity: int
    discount_percent: float = 0.0


class Inventory:
    def __init__(self):
        self.items = {}

    def add(self, name, unit_price, quantity, discount_percent=0.0):
        if quantity < 0:
            raise ValueError("quantity must not be negative")
        if name in self.items:
            self.items[name].quantity += quantity
        else:
            self.items[name] = Item(name, unit_price, quantity, discount_percent)

    def remove(self, name, quantity):
        """Take stock out; removing more than is held is an error."""
        item = self.items[name]
        item.quantity -= quantity

    def quantity(self, name):
        return self.items[name].quantity if name in self.items else 0
"""Prices for inventory lines."""


def line_price(item):
    """Value of one inventory line after the item's percentage discount."""
    discounted = item.unit_price * item.discount_percent / 100
    return round(discounted * item.quantity, 2)
"""Plain-text stock reports."""

from inventory.pricing import line_price


def total_value(inventory):
    """Total value of all stock, after discounts."""
    return round(sum(item.quantity for item in inventory.items.values()), 2)


def render(inventory):
    lines = [f"{'item':<12}{'qty':>5}{'value':>10}"]
    for item in sorted(inventory.items.values(), key=lambda i: i.name):
        lines.append(f"{item.name:<12}{item.quantity:>5}{line_price(item):>10.2f}")
    lines.append(f"{'total':<17}{total_value(inventory):>10.2f}")
    return "\n".join(lines)
"""Run the project's checks and print one PASS/FAIL line per check."""

import sys

from inventory import Inventory, line_price, total_value
from inventory.models import Item


def check_remove_guard():
    inv = Inventory()
    inv.add("bolt", 0.5, 3)
    try:
        inv.remove("bolt", 5)
    except ValueError:
        return inv.quantity("bolt") == 3
    return False


def check_discount():
    return line_price(Item("nut", 2.0, 10, discount_percent=25)) == 15.0


def check_total():
    inv = Inventory()
    inv.add("nut", 2.0, 10, discount_percent=25)
    inv.add("washer", 0.1, 50)
    return total_value(inv) == 20.0


CHECKS = [check_remove_guard, check_discount, check_total]


def main():
    failed = 0
    for check in CHECKS:
        try:
            ok = check()
        except Exception as exc:  # report, never crash the runner
            ok = False
            print(f"FAIL {check.__name__}: {type(exc).__name__}: {exc}")
            failed += 1
            continue
        print(f"{'PASS' if ok else 'FAIL'} {check.__name__}")
        failed += not ok
    print(f"{len(CHECKS) - failed}/{len(CHECKS)} checks passed")
    sys.exit(1 if failed else 0)


if __name__ == "__main__":
    main()
